// /frontend-react/src/components/MedicalHistory.js

import React from 'react';
import { useTranslation } from 'react-i18next';
import HeaderBar from './HeaderBar'; // Assuming HeaderBar is imported from parent directory

// --- LOCAL MOCK DATA ---
const mockHistoryData = {
    // Simple summary text for the elderly user
    simpleMedication: "You currently take Blood Pressure Pill (5mg) and a Multivitamin. Both taken in the morning.",
    simpleSurgery: "You had a minor knee surgery (left leg) in 2022. No further action needed.",
    simpleVaccination: "You are up to date on your Flu shot (2025) and COVID booster (2024).",

    // PDF links for others' reference (Precision data)
    pdfLinks: {
        medication: "Link_to_detailed_Medication_History_Report.pdf",
        surgery: "Link_to_detailed_Surgical_Records_PDF.pdf",
        vaccination: "Link_to_official_Vaccination_Record.pdf",
    }
};

const PHONE_MAX_WIDTH = '450px';

function MedicalHistory({ isEasyMode, goToPage, onMenuClick }) {
    const { t } = useTranslation();

    const headerFontSize = isEasyMode ? 40 : 28;
    const baseFontSize = isEasyMode ? 28 : 18; // Base text size for labels

    // Style for the main clickable cards
    const historyCardStyle = (color, emoji) => ({
        padding: '25px',
        borderRadius: '20px',
        margin: '25px auto',
        backgroundColor: color.bg,
        border: `4px solid ${color.border}`,
        textAlign: 'center',
        maxWidth: '400px',
        cursor: 'pointer',
        boxShadow: `0 8px 15px ${color.border}4D`,
        transition: 'all 0.3s',
    });

    // Color definitions for visual clarity
    const colors = {
        medication: { bg: '#E8F0FE', border: '#1A73E8', emoji: '💊' }, // Blue
        surgery: { bg: '#FFFDE7', border: '#FFD700', emoji: '🏥' },  // Yellow/Gold
        vaccination: { bg: '#E6FBE6', border: '#4CAF50', emoji: '💉' }, // Green
    };

    /**
     * Handles card click: Shows simple info OR provides PDF link for others.
     * @param {string} key - 'medication', 'surgery', or 'vaccination'
     */
    const handleHistoryClick = (key) => {
        const simpleInfo = mockHistoryData[`simple${key.charAt(0).toUpperCase() + key.slice(1)}`];
        const pdfLink = mockHistoryData.pdfLinks[key];

        // 1. Show simple info for the user immediately
        alert(`${t(`medical_history.${key}_title`)}: \n\n${simpleInfo}`);

        // 2. Log the precise PDF link for later use by the caregiver/doctor
        console.log(`Precise PDF for ${key}: ${pdfLink}`); 
        // In a real application, you might show a second button here: "Share PDF"
    };

    return (
        <div 
            style={{
                padding: '0 20px 20px 20px',
                maxWidth: PHONE_MAX_WIDTH,
                margin: '0 auto',
            }}
        >
            <HeaderBar
                title={t('header.title_history')}
                onBackClick={() => goToPage('medical-dashboard')}
                onMenuClick={onMenuClick}
                isEasyMode={isEasyMode}
            />

            <h2 style={{ fontSize: headerFontSize, margin: '60px 0 20px 0', textAlign: 'center', color: '#333' }}>
                {t('medical_history.title')}
            </h2>

            {/* --- 1. Medication History Card --- */}
            <div 
                onClick={() => handleHistoryClick('medication')}
                style={historyCardStyle(colors.medication)}
            >
                <span style={{ fontSize: isEasyMode ? '80px' : '50px', display: 'block' }}>
                    {colors.medication.emoji}
                </span>
                <p style={{ fontSize: baseFontSize, fontWeight: '900', margin: '10px 0 0 0', color: colors.medication.border }}>
                    {t('medical_history.medication_title')}
                </p>
                <p style={{ fontSize: isEasyMode ? '20px' : '14px', margin: '5px 0 0 0', color: '#666' }}>
                    {t('medical_history.medication_subtitle')}
                </p>
            </div>

            {/* --- 2. Surgery History Card --- */}
            <div 
                onClick={() => handleHistoryClick('surgery')}
                style={historyCardStyle(colors.surgery)}
            >
                <span style={{ fontSize: isEasyMode ? '80px' : '50px', display: 'block' }}>
                    {colors.surgery.emoji}
                </span>
                <p style={{ fontSize: baseFontSize, fontWeight: '900', margin: '10px 0 0 0', color: colors.surgery.border }}>
                    {t('medical_history.surgery_title')}
                </p>
                 <p style={{ fontSize: isEasyMode ? '20px' : '14px', margin: '5px 0 0 0', color: '#666' }}>
                    {t('medical_history.surgery_subtitle')}
                </p>
            </div>

            {/* --- 3. Vaccination Record Card --- */}
            <div 
                onClick={() => handleHistoryClick('vaccination')}
                style={historyCardStyle(colors.vaccination)}
            >
                <span style={{ fontSize: isEasyMode ? '80px' : '50px', display: 'block' }}>
                    {colors.vaccination.emoji}
                </span>
                <p style={{ fontSize: baseFontSize, fontWeight: '900', margin: '10px 0 0 0', color: colors.vaccination.border }}>
                    {t('medical_history.vaccination_title')}
                </p>
                 <p style={{ fontSize: isEasyMode ? '20px' : '14px', margin: '5px 0 0 0', color: '#666' }}>
                    {t('medical_history.vaccination_subtitle')}
                </p>
            </div>

            <p style={{ fontSize: isEasyMode ? '22px' : '14px', margin: '40px auto 10px auto', maxWidth: '400px', textAlign: 'center', color: '#999' }}>
                * {t('medical_history.disclaimer')}
            </p>

        </div>
    );
}

export default MedicalHistory;
